const D = { energy: .62, scale: 1, speed: 1, density: .55, fold: .5, hue: 42, x: .5, y: .5, style: 'gilt', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// ISLIMI -- Islamic biomorphic arabesque scrollwork. Split-leaf (rumi) vines
// spiral out of a central rosette in N-fold symmetry, forever unfurling. A band
// of gilding shimmer travels around and through the medallion on incommensurate
// rates so the symmetry never freezes; leaf tips breathe as if still growing.
// gilt leaf on a tinted ground, cloisonne enamel, copperplate engraving, or a
// cyan schematic.
// -----------------------------------------------------------------------------

const u = Math.min(width, height);
const cx = P.x * width, cy = P.y * height;
const sd = (P.seed | 0);
const fr = i => { let h = (Math.imul((i ^ sd) | 0, 374761393) + 0x9e3779b9) | 0; h = Math.imul(h ^ (h >>> 15), 668265263); h ^= h >>> 13; return ((h >>> 0) % 100000) / 100000; };

// ---- geometry: build two master strands (spiral vine + leaf anchors) --------
const nFold = Math.round(5 + P.fold * 9);          // 5..14 arms
function buildStrand(off) {
  const pts = [], leaves = [];
  const turns = 1.6 + fr(off * 3 + 1) * 0.9;
  const NS = 44;
  const wav = 0.12 + fr(off * 5 + 2) * 0.1;
  for (let i = 0; i <= NS; i++) {
    const s = i / NS;
    const ang = s * turns * Math.PI * 2 + fr(off + 9) * 6.28;
    const rad = 0.12 + s * 0.92;                    // spiral outward, normalized
    const wob = wav * Math.sin(s * 9 + off) * (0.3 + s);
    pts.push({ x: Math.cos(ang) * rad + Math.cos(ang + 1.57) * wob, y: Math.sin(ang) * rad + Math.sin(ang + 1.57) * wob, s });
  }
  const nl = 6 + Math.round(fr(off + 3) * 4);
  for (let l = 0; l < nl; l++) {
    const t = 0.18 + (l / nl) * 0.78 + fr(l * 7 + off) * 0.04;
    leaves.push({ t, side: (l % 2 ? 1 : -1), size: 0.09 + fr(l * 11 + off) * 0.09, ph: fr(l * 13 + off) * 6.28, split: fr(l * 3 + off) > 0.5 });
  }
  return { pts, leaves };
}
if (!S.built || S.seedUsed !== P.seed || S.foldUsed !== nFold) {
  S.seedUsed = P.seed; S.foldUsed = nFold;
  S.A = buildStrand(1.3); S.B = buildStrand(7.7);
}

// ---- palette per style ------------------------------------------------------
const st = P.style;
let grd, veinLo, veinHi, leafLo, leafHi, edge, sat, engrave = false;
if (st === 'enamel') {
  grd = [ (P.hue + 200) % 360, 55, 10 ]; veinLo = [40, 30, 22]; veinHi = [46, 22, 78];
  leafLo = [(P.hue + 180) % 360, 78, 30]; leafHi = [(P.hue + 170) % 360, 82, 62]; edge = [45, 20, 92]; sat = 1;
} else if (st === 'engraving') {
  grd = [34, 16, 50]; veinLo = [32, 22, 16]; veinHi = [34, 12, 40];
  leafLo = [33, 18, 30]; leafHi = [33, 10, 60]; edge = [34, 8, 74]; sat = 0.5; engrave = true;
} else if (st === 'blueprint') {
  grd = [220, 62, 14]; veinLo = [200, 60, 40]; veinHi = [190, 45, 78];
  leafLo = [205, 55, 26]; leafHi = [195, 50, 60]; edge = [188, 40, 92]; sat = 0.8; engrave = true;
} else { // gilt (default)
  grd = [ (P.hue + 205) % 360, 62, 15 ]; veinLo = [ (P.hue - 6 + 360) % 360, 70, 28 ]; veinHi = [ (P.hue + 8) % 360, 55, 92 ];
  leafLo = [ (P.hue - 4 + 360) % 360, 72, 34 ]; leafHi = [ (P.hue + 6) % 360, 48, 96 ]; edge = [ (P.hue + 12) % 360, 30, 100 ]; sat = 1;
}

// ---- background ground with radial burnish ----------------------------------
push();
noStroke(); rectMode(CORNER);
fill(grd[0], grd[1], grd[2]); rect(0, 0, width, height);
// vignette / central pool of light so ground is textured, not flat
for (let r = 6; r >= 0; r--) {
  const rr = u * (0.18 + r * 0.16);
  fill(grd[0], Math.max(0, grd[1] - 8), grd[2] + (6 - r) * (engrave ? 3 : 4), engrave ? 8 : 11);
  ellipse(cx, cy, rr * 2, rr * 2);
}
pop();

// ---- animation drivers ------------------------------------------------------
const sp = 0.3 + P.speed * 0.9;
const glow = 0.5 + P.energy * 1.2 + A.rms * 0.25;
const rot = K.t * 0.035 * sp + 0.18 * Math.sin(K.t * 0.11 * sp);     // two incommensurate rotation rates
const shimAng = K.t * 0.23 * sp;                                     // gilding hotspot travels around
const shimRad = 0.55 + 0.42 * Math.sin(K.t * 0.37 * sp + 1.1);      // ...and in/out
const R = u * (0.62 + 0.16 * Math.sin(K.t * 0.5)) * P.scale * (0.85 + P.fold * 0.0);
const RR = u * 0.72 * P.scale;

function shimmer(ax, ay, rn) {                                       // hotspot brightness 0..1, breaks symmetry
  let da = Math.atan2(ay, ax) - shimAng;
  da = Math.atan2(Math.sin(da), Math.cos(da));
  const dr = rn - shimRad;
  return Math.exp(-(da * da) * 2.2) * Math.exp(-(dr * dr) * 5.5);
}

// ---- draw one strand (vine + leaves) in normalized space --------------------
function leaf(px, py, nx, ny, size, ph, split, brt) {
  const tx = -ny, ty = nx;                                           // tangent
  const w = size * RR;
  const unf = 0.82 + 0.18 * Math.sin(K.t * 0.9 * sp + ph);           // unfurl breathe (growth)
  const L = w * (1.7) * unf, W = w * 0.9;
  push(); translate(px, py);
  const bx = nx, by = ny;                                            // outward normal = leaf grows outward
  // leaf body: teardrop via bezier
  const lo = leafLo, hi = leafHi;
  noStroke();
  fill(lo[0], lo[1] * sat, lo[2]);
  beginShape();
  vertex(0, 0);
  bezierVertex(bx * L * 0.3 + tx * W, by * L * 0.3 + ty * W, bx * L * 0.8 + tx * W * 0.5, by * L * 0.8 + ty * W * 0.5, bx * L, by * L);
  bezierVertex(bx * L * 0.8 - tx * W * 0.5, by * L * 0.8 - ty * W * 0.5, bx * L * 0.3 - tx * W, by * L * 0.3 - ty * W, 0, 0);
  endShape(CLOSE);
  // highlight lobe (offset toward light) -> modelled, not flat
  const hb = Math.min(100, hi[2] * (0.6 + 0.5 * brt) * glow);
  fill(hi[0], hi[1] * sat, hb, engrave ? 55 : 80);
  beginShape();
  vertex(bx * L * 0.12, by * L * 0.12);
  bezierVertex(bx * L * 0.35 + tx * W * 0.5, by * L * 0.35 + ty * W * 0.5, bx * L * 0.75 + tx * W * 0.2, by * L * 0.75 + ty * W * 0.2, bx * L * 0.95, by * L * 0.95);
  bezierVertex(bx * L * 0.7, by * L * 0.7, bx * L * 0.4, by * L * 0.4, bx * L * 0.12, by * L * 0.12);
  endShape(CLOSE);
  if (split) { // second small lobe -> split-leaf rumi
    fill(lo[0], lo[1] * sat, lo[2] + 6, 78);
    ellipse(bx * L * 0.5 - tx * W * 0.7, by * L * 0.5 - ty * W * 0.7, W * 0.9, W * 1.3);
  }
  // bright rim
  stroke(edge[0], edge[1] * sat, Math.min(100, edge[2] * (0.5 + 0.6 * brt)), engrave ? 40 : 70);
  strokeWeight(Math.max(0.5, RR * 0.004));
  noFill();
  beginShape();
  vertex(0, 0);
  bezierVertex(bx * L * 0.3 + tx * W, by * L * 0.3 + ty * W, bx * L * 0.8 + tx * W * 0.5, by * L * 0.8 + ty * W * 0.5, bx * L, by * L);
  endShape();
  pop();
}

function drawStrand(strand) {
  const pts = strand.pts;
  // vine: layered tapered line segments for metallic relief (weight varies per seg + shimmer)
  noFill();
  for (let i = 1; i < pts.length; i++) {
    const a = pts[i - 1], b = pts[i];
    const rn = (a.s + b.s) * 0.5;                                    // 0..~1 along radius
    const sh = shimmer((a.x + b.x) * 0.5, (a.y + b.y) * 0.5, 0.12 + rn);
    const taper = 1 - rn * 0.7;
    const brt = Math.min(1, 0.35 + sh * 1.4 * glow);
    // shadow underlay
    stroke(veinLo[0], veinLo[1] * sat, veinLo[2], engrave ? 60 : 90);
    strokeWeight(RR * 0.03 * taper + 1.2);
    line(a.x * RR, a.y * RR, b.x * RR, b.y * RR);
    // gold body
    stroke(veinHi[0], veinHi[1] * sat, Math.min(100, veinHi[2] * (0.55 + 0.5 * brt)), engrave ? 70 : 100);
    strokeWeight(RR * 0.016 * taper + 0.6);
    line(a.x * RR, a.y * RR, b.x * RR, b.y * RR);
    // bright core highlight
    if (!engrave) { stroke(edge[0], edge[1] * sat * 0.6, Math.min(100, 60 + brt * 40), 70 * brt); strokeWeight(RR * 0.006 * taper + 0.3); line(a.x * RR, a.y * RR, b.x * RR, b.y * RR); }
  }
  // leaves
  for (const lf of strand.leaves) {
    const idx = Math.min(pts.length - 2, Math.floor(lf.t * (pts.length - 1)));
    const a = pts[idx], b = pts[idx + 1];
    const px = a.x * RR, py = a.y * RR;
    let nx = a.x, ny = a.y; const nl = Math.hypot(nx, ny) || 1; nx /= nl; ny /= nl;
    nx *= lf.side; ny *= lf.side;
    const sh = shimmer(a.x, a.y, 0.12 + a.s);
    const brt = Math.min(1, 0.3 + sh * 1.5 * glow);
    leaf(px, py, nx, ny, lf.size, lf.ph, lf.split, brt);
  }
}

// ---- compose the medallion --------------------------------------------------
push();
translate(cx, cy);
if (st === 'enamel') blendMode(BLEND);
for (let k = 0; k < nFold; k++) {
  push();
  rotate(rot + (k / nFold) * Math.PI * 2);
  drawStrand(k % 2 ? S.B : S.A);
  pop();
}
// central rosette
const cShim = 0.6 + 0.4 * Math.sin(shimAng * 2);
noStroke();
for (let r = 5; r >= 0; r--) {
  const rr = u * 0.02 * P.scale * (r + 1);
  fill(veinHi[0], veinHi[1] * sat, Math.min(100, veinHi[2] * (0.5 + 0.5 * cShim) * (1 - r * 0.12)), engrave ? 70 : 100);
  const petals = nFold * 2;
  beginShape();
  for (let a = 0; a <= petals; a++) {
    const ang = (a / petals) * Math.PI * 2 + rot * 0.5;
    const pr = rr * (0.75 + 0.25 * Math.cos(ang * petals * 0.5 + rot));
    curveVertex(Math.cos(ang) * pr, Math.sin(ang) * pr);
  }
  endShape(CLOSE);
}
fill(edge[0], edge[1] * sat, Math.min(100, 70 + cShim * 30), 90);
ellipse(0, 0, u * 0.03 * P.scale, u * 0.03 * P.scale);
pop();

blendMode(BLEND);
if (P.alpha < 100) { push(); noStroke(); rectMode(CORNER); fill(grd[0], grd[1], grd[2], 100 - Math.max(0, Math.min(100, P.alpha))); rect(0, 0, width, height); pop(); }
drawingContext.shadowBlur = 0;
